package com.example.lokihealbe;
import android.content.*;import android.security.keystore.*;import org.json.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import java.security.*;import java.io.*;
final class SnapshotStore {
 private static javax.crypto.SecretKey key()throws Exception{KeyStore s=KeyStore.getInstance("AndroidKeyStore");s.load(null);String alias="loki-healbe-sdk-cache-v1";if(!s.containsAlias(alias)){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(alias,3).setKeySize(256).setBlockModes("GCM").setEncryptionPaddings("NoPadding").build());g.generateKey();}return (javax.crypto.SecretKey)s.getKey(alias,null);}
 static synchronized void write(Context c,JSONObject data)throws Exception{byte[] plain=data.toString().getBytes("UTF-8");if(plain.length>4096)throw new IOException("cache size");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());File tmp=new File(c.getFilesDir(),"energy.tmp");try(FileOutputStream out=new FileOutputStream(tmp)){out.write(cipher.getIV());out.write(cipher.doFinal(plain));out.getFD().sync();}if(!tmp.renameTo(new File(c.getFilesDir(),"energy.gcm")))throw new IOException("cache commit");}
 static synchronized JSONObject read(Context c){try{File f=new File(c.getFilesDir(),"energy.gcm");if(!f.exists()||f.length()>8192)return new JSONObject();byte[] bytes=java.nio.file.Files.readAllBytes(f.toPath());if(bytes.length<28)return new JSONObject();Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,java.util.Arrays.copyOf(bytes,12)));return new JSONObject(new String(cipher.doFinal(bytes,12,bytes.length-12),"UTF-8"));}catch(Exception e){return new JSONObject();}}
 static synchronized void clear(Context c){new File(c.getFilesDir(),"energy.gcm").delete();}
}
